from typing import Optional, Tuple

Triple = Tuple[int, int, int]
WITNESSES: dict[int, Triple] = {
    0: (0, 0, 0), 1: (1, 0, 0), 2: (1, 1, 0), 3: (1, 1, 1),
    6: (-1, -1, -1), 7: (-1, -1, 0), 8: (-1, 0, 0),
}

def modulo_nine_witness(k: int) -> Optional[Triple]:
    """Return a witness modulo nine, or None exactly for residues 4 and 5."""
    witness = WITNESSES.get(k % 9)
    if witness is not None:
        assert sum(x ** 3 for x in witness) % 9 == k % 9
    return witness

from typing import Optional, Tuple

Triple = Tuple[int, int, int]

def bounded_three_cube_search(k: int, bound: int) -> Optional[Triple]:
    """Find x^3+y^3+z^3=k with all coordinates in [-bound,bound]."""
    if bound < 0:
        raise ValueError("bound must be nonnegative")
    values = range(-bound, bound + 1)
    pairs: dict[int, Tuple[int, int]] = {}
    for x in values:
        for y in values:
            pairs.setdefault(x**3 + y**3, (x, y))
    for z in values:
        pair = pairs.get(k - z**3)
        if pair is not None:
            answer = (pair[0], pair[1], z)
            assert sum(v**3 for v in answer) == k
            return answer
    return None

